function evo_slark_str_w.prototype.OnSpellStart(self)
    if not IsServer() then
        return
    end
    local caster = self:GetCaster()
    local target = self:GetCursorTarget()
    if not caster or caster:IsNull() or not target or target:IsNull() then
        return
    end
    if target:TriggerSpellAbsorb(self) then
        return
    end
    local level = self:GetLevel()
    local baseDmg = self:GetSpecialValueFor("base_damage")
    local strPct = self:GetSpecialValueFor("str_pct") / 100
    local str = caster:IsRealHero() and caster:GetStrength() or 0
    local totalDmg = baseDmg + str * strPct
    if level >= 2 then
        totalDmg = totalDmg + target:GetMaxHealth() * 0.06
        target:AddNewModifier(caster, self, "modifier_evo_slark_str_w_slow", {duration = 3})
    end
    local executeBonus = level >= 3 and target:GetHealthPercent() <= 40
    if executeBonus then
        totalDmg = totalDmg * 1.5
    end
    caster:EmitSound("Hero_LifeStealer.OpenWounds.Cast")
    caster:PerformAttack(
        target,
        true,
        true,
        true,
        false,
        false,
        false,
        false
    )
    local dealt = ApplyDamage({
        victim = target,
        attacker = caster,
        ability = self,
        damage = totalDmg,
        damage_type = 1
    })
